CREATE TABLE `users` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`email` text NOT NULL,`password_hash` text NOT NULL,`name` text NOT NULL,`role` text NOT NULL DEFAULT "user",`is_active` numeric NOT NULL DEFAULT true,`avatar_path` text,`password_reset_token` text,`password_reset_expires` datetime,`token_version` integer NOT NULL DEFAULT 0);
CREATE TABLE `properties` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`user_id` integer NOT NULL,`name` text NOT NULL,`address` text,`type` text,`start_date` datetime,`end_date` datetime,`is_current` numeric NOT NULL DEFAULT false,`residents` integer DEFAULT 1,CONSTRAINT `fk_properties_owner` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
CREATE TABLE `household_members` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`property_id` integer NOT NULL,`user_id` integer,`name` text NOT NULL,`role` text,`is_virtual` numeric NOT NULL DEFAULT false,CONSTRAINT `fk_household_members_property` FOREIGN KEY (`property_id`) REFERENCES `properties`(`id`),CONSTRAINT `fk_household_members_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
CREATE TABLE `categories` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`user_id` integer,`slug` text,`name` text NOT NULL,`icon` text,`color` text,`is_default` numeric NOT NULL DEFAULT false,CONSTRAINT `fk_categories_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
CREATE TABLE `subcategories` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`category_id` integer NOT NULL,`slug` text,`name` text NOT NULL,CONSTRAINT `fk_categories_subcategories` FOREIGN KEY (`category_id`) REFERENCES `categories`(`id`) ON DELETE CASCADE);
CREATE TABLE `utilities` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`user_id` integer NOT NULL,`property_id` integer NOT NULL,`type` text NOT NULL,`provider` text NOT NULL,`customer_code` text,`service_code` text,`address` text,`start_date` datetime,`end_date` datetime,`is_active` numeric NOT NULL DEFAULT true,`is_metered` numeric NOT NULL,`power_capacity` real,`allows_self_reading` numeric DEFAULT true,`comparison_threshold` real DEFAULT 2,`threshold_per_day` real DEFAULT 1,`reading_match_days` integer DEFAULT 15,`recurring_amount` real,`billing_interval` integer NOT NULL DEFAULT 1,`billing_unit` text NOT NULL DEFAULT "month",`default_category_id` integer,`paid_by_member_id` integer,`is_domiciled` numeric NOT NULL DEFAULT false,`is_installment_based` numeric NOT NULL DEFAULT false,`split_override` text NOT NULL DEFAULT "",`split_member_ids` text,`customer_portal` text,`notes` text,`currency` text NOT NULL DEFAULT "",CONSTRAINT `fk_utilities_property` FOREIGN KEY (`property_id`) REFERENCES `properties`(`id`),CONSTRAINT `fk_utilities_default_category` FOREIGN KEY (`default_category_id`) REFERENCES `categories`(`id`),CONSTRAINT `fk_utilities_paid_by_member` FOREIGN KEY (`paid_by_member_id`) REFERENCES `household_members`(`id`));
CREATE TABLE `meter_readings` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`utility_id` integer NOT NULL,`reading_date` datetime NOT NULL,`value_f1` real,`value_f2` real,`value_f3` real,`value` real,`source` text DEFAULT "manual",`photo_url` text,`notes` text,CONSTRAINT `fk_utilities_readings` FOREIGN KEY (`utility_id`) REFERENCES `utilities`(`id`) ON DELETE CASCADE);
CREATE TABLE `bills` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`utility_id` integer NOT NULL,`bill_number` text NOT NULL,`user_reading_id` integer,`issue_date` datetime NOT NULL,`period_start` datetime NOT NULL,`period_end` datetime NOT NULL,`due_date` datetime NOT NULL,`provider_reading_date` datetime,`provider_reading_f1` real,`provider_reading_f2` real,`provider_reading_f3` real,`provider_reading` real,`reading_type` text,`meter_serial` text,`reading_start_date` datetime,`reading_start_value` real,`reading_end_date` datetime,`reading_end_value` real,`consumption_total` real NOT NULL,`consumption_f1` real,`consumption_f2` real,`consumption_f3` real,`conversion_coefficient` real,`amount_total` real NOT NULL,`amount_energy` real,`amount_fixed` real,`amount_taxes` real,`amount_vat` real,`original_amount` real,`original_currency` text,`is_paid` numeric NOT NULL DEFAULT false,`paid_date` datetime,`pdf_url` text,`parsed_data` text,CONSTRAINT `fk_bills_user_reading` FOREIGN KEY (`user_reading_id`) REFERENCES `meter_readings`(`id`),CONSTRAINT `fk_utilities_bills` FOREIGN KEY (`utility_id`) REFERENCES `utilities`(`id`));
CREATE TABLE `bill_installments` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`bill_id` integer NOT NULL,`number` integer NOT NULL DEFAULT 1,`due_date` datetime NOT NULL,`amount` real NOT NULL,`is_paid` numeric NOT NULL DEFAULT false,`paid_at` datetime,`expense_id` integer,CONSTRAINT `fk_bill_installments_expense` FOREIGN KEY (`expense_id`) REFERENCES `expenses`(`id`) ON DELETE SET NULL,CONSTRAINT `fk_bills_installments` FOREIGN KEY (`bill_id`) REFERENCES `bills`(`id`) ON DELETE CASCADE);
CREATE TABLE `projects` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`user_id` integer NOT NULL,`property_id` integer,`name` text NOT NULL,`icon` text,`budget` real NOT NULL,`start_date` datetime NOT NULL,`end_date` datetime NOT NULL,`description` text,`status` text NOT NULL DEFAULT "active",CONSTRAINT `fk_projects_owner` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`),CONSTRAINT `fk_projects_property` FOREIGN KEY (`property_id`) REFERENCES `properties`(`id`));
CREATE TABLE `expenses` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`user_id` integer NOT NULL,`property_id` integer,`category_id` integer NOT NULL,`subcategory_id` integer,`project_id` integer,`bill_id` integer,`bill_installment_id` integer,`amount` real NOT NULL,`original_amount` real,`original_currency` text,`date` datetime NOT NULL,`description` text,`attachment_url` text,`paid_by_member_id` integer NOT NULL DEFAULT 0,`is_split` numeric NOT NULL DEFAULT false,`is_long_term_debt` numeric NOT NULL DEFAULT false,CONSTRAINT `fk_expenses_paid_by` FOREIGN KEY (`paid_by_member_id`) REFERENCES `household_members`(`id`),CONSTRAINT `fk_expenses_bill` FOREIGN KEY (`bill_id`) REFERENCES `bills`(`id`),CONSTRAINT `fk_expenses_bill_installment` FOREIGN KEY (`bill_installment_id`) REFERENCES `bill_installments`(`id`),CONSTRAINT `fk_expenses_property` FOREIGN KEY (`property_id`) REFERENCES `properties`(`id`),CONSTRAINT `fk_expenses_category` FOREIGN KEY (`category_id`) REFERENCES `categories`(`id`),CONSTRAINT `fk_projects_expenses` FOREIGN KEY (`project_id`) REFERENCES `projects`(`id`) ON DELETE SET NULL,CONSTRAINT `fk_expenses_subcategory` FOREIGN KEY (`subcategory_id`) REFERENCES `subcategories`(`id`));
CREATE TABLE `utility_rates` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`utility_id` integer NOT NULL,`effective_date` datetime NOT NULL,`rate_f1` real,`rate_f2` real,`rate_f3` real,`rate_fixed` real,`rate_unit` real,`notes` text,CONSTRAINT `fk_utilities_rates` FOREIGN KEY (`utility_id`) REFERENCES `utilities`(`id`) ON DELETE CASCADE);
CREATE TABLE `price_changes` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`utility_id` integer NOT NULL,`effective_date` datetime NOT NULL,`old_amount` real NOT NULL,`new_amount` real NOT NULL,`reason` text,`cancellation_deadline` datetime,`source_bill_id` integer,CONSTRAINT `fk_price_changes_source_bill` FOREIGN KEY (`source_bill_id`) REFERENCES `bills`(`id`) ON DELETE SET NULL,CONSTRAINT `fk_utilities_price_changes` FOREIGN KEY (`utility_id`) REFERENCES `utilities`(`id`) ON DELETE CASCADE);
CREATE TABLE `service_communications` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`utility_id` integer NOT NULL,`bill_id` integer,`type` text NOT NULL,`title` text NOT NULL,`content` text,`action_deadline` datetime,`is_important` numeric NOT NULL DEFAULT false,`is_read` numeric NOT NULL DEFAULT false,CONSTRAINT `fk_service_communications_bill` FOREIGN KEY (`bill_id`) REFERENCES `bills`(`id`) ON DELETE SET NULL,CONSTRAINT `fk_utilities_communications` FOREIGN KEY (`utility_id`) REFERENCES `utilities`(`id`) ON DELETE CASCADE);
CREATE TABLE `project_members` (`project_id` integer,`user_id` integer,`role` text NOT NULL DEFAULT "member",PRIMARY KEY (`project_id`,`user_id`),CONSTRAINT `fk_project_members_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`),CONSTRAINT `fk_projects_members` FOREIGN KEY (`project_id`) REFERENCES `projects`(`id`) ON DELETE CASCADE,CONSTRAINT `fk_project_members_project` FOREIGN KEY (`project_id`) REFERENCES `projects`(`id`) ON DELETE CASCADE);
CREATE TABLE `user_settings` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`user_id` integer NOT NULL,`language` text NOT NULL DEFAULT "en",`currency` text NOT NULL DEFAULT "EUR",`theme` text NOT NULL DEFAULT "auto",`color_theme` text NOT NULL DEFAULT "slate",`date_format` text NOT NULL DEFAULT "DD/MM/YYYY",`default_split_with_member_ids` text,`email_notifications` numeric NOT NULL DEFAULT true,`in_app_notifications` numeric NOT NULL DEFAULT true,`bill_due_alert_days` integer NOT NULL DEFAULT 3,`reading_reminder_days` integer NOT NULL DEFAULT 7,`notification_retention_days` integer NOT NULL DEFAULT 90,`notify_join_requests` numeric NOT NULL DEFAULT false,`notify_shared_expenses` numeric NOT NULL DEFAULT false,`anomaly_threshold` real NOT NULL DEFAULT 5,`onboarding_completed` numeric NOT NULL DEFAULT false,CONSTRAINT `fk_user_settings_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
CREATE TABLE `household_settings` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`property_id` integer NOT NULL,`split_mode` numeric NOT NULL DEFAULT false,`default_split_type` text NOT NULL DEFAULT "equal",CONSTRAINT `fk_household_settings_property` FOREIGN KEY (`property_id`) REFERENCES `properties`(`id`));
CREATE TABLE `settlements` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`property_id` integer NOT NULL,`from_member_id` integer NOT NULL,`to_member_id` integer NOT NULL,`amount` real NOT NULL,`date` datetime NOT NULL,`payment_method` text,`note` text,`target_expense_id` integer,CONSTRAINT `fk_settlements_target_expense` FOREIGN KEY (`target_expense_id`) REFERENCES `expenses`(`id`) ON DELETE SET NULL,CONSTRAINT `fk_settlements_property` FOREIGN KEY (`property_id`) REFERENCES `properties`(`id`),CONSTRAINT `fk_settlements_from_member` FOREIGN KEY (`from_member_id`) REFERENCES `household_members`(`id`),CONSTRAINT `fk_settlements_to_member` FOREIGN KEY (`to_member_id`) REFERENCES `household_members`(`id`));
CREATE TABLE `expense_splits` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`expense_id` integer NOT NULL,`member_id` integer NOT NULL,`amount` real NOT NULL,`settled_amount` real NOT NULL DEFAULT 0,`is_settled` numeric NOT NULL DEFAULT false,`settled_at` datetime,`settlement_id` integer,CONSTRAINT `fk_expense_splits_member` FOREIGN KEY (`member_id`) REFERENCES `household_members`(`id`),CONSTRAINT `fk_expense_splits_settlement` FOREIGN KEY (`settlement_id`) REFERENCES `settlements`(`id`) ON DELETE SET NULL,CONSTRAINT `fk_expenses_splits` FOREIGN KEY (`expense_id`) REFERENCES `expenses`(`id`) ON DELETE CASCADE);
CREATE TABLE `settlement_allocations` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`settlement_id` integer NOT NULL,`expense_split_id` integer NOT NULL,`amount` real NOT NULL,`kind` text NOT NULL DEFAULT "payment",CONSTRAINT `fk_settlement_allocations_expense_split` FOREIGN KEY (`expense_split_id`) REFERENCES `expense_splits`(`id`),CONSTRAINT `fk_settlements_allocations` FOREIGN KEY (`settlement_id`) REFERENCES `settlements`(`id`) ON DELETE CASCADE);
CREATE TABLE `bill_templates` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`property_id` integer NOT NULL,`user_id` integer,`name` text NOT NULL,`provider` text NOT NULL,`utility_type` text NOT NULL,`is_default` numeric NOT NULL DEFAULT false,`extraction_rules` text,CONSTRAINT `fk_bill_templates_property` FOREIGN KEY (`property_id`) REFERENCES `properties`(`id`),CONSTRAINT `fk_bill_templates_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
CREATE TABLE `contract_templates` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`user_id` integer NOT NULL,`name` text NOT NULL,`provider` text NOT NULL,`utility_type` text NOT NULL,`is_default` numeric NOT NULL DEFAULT false,`extraction_rules` text,CONSTRAINT `fk_contract_templates_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
CREATE TABLE `expense_templates` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`user_id` integer NOT NULL,`name` text NOT NULL,`icon` text,`amount` real,`description` text,`category_id` integer NOT NULL,`subcategory_id` integer,`project_id` integer,`currency` text,`sort_order` integer NOT NULL DEFAULT 0,CONSTRAINT `fk_expense_templates_subcategory` FOREIGN KEY (`subcategory_id`) REFERENCES `subcategories`(`id`),CONSTRAINT `fk_expense_templates_project` FOREIGN KEY (`project_id`) REFERENCES `projects`(`id`) ON DELETE SET NULL,CONSTRAINT `fk_expense_templates_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`),CONSTRAINT `fk_expense_templates_category` FOREIGN KEY (`category_id`) REFERENCES `categories`(`id`));
CREATE TABLE `property_join_requests` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`user_id` integer NOT NULL,`property_id` integer NOT NULL,`status` text NOT NULL DEFAULT "pending",`resolved_by` integer,`resolved_at` datetime,CONSTRAINT `fk_property_join_requests_property` FOREIGN KEY (`property_id`) REFERENCES `properties`(`id`),CONSTRAINT `fk_property_join_requests_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
CREATE TABLE `notifications` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`user_id` integer NOT NULL,`type` text NOT NULL,`title` text NOT NULL,`content` text,`is_read` numeric NOT NULL DEFAULT false,`related_id` integer,`property_id` integer,CONSTRAINT `fk_notifications_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`),CONSTRAINT `fk_notifications_property` FOREIGN KEY (`property_id`) REFERENCES `properties`(`id`));
